import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.D3GK3dQI.js";const u=JSON.parse('{"title":"Kubernetes Gateway Exporter Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"architecture.md","filePath":"architecture.md"}'),r={name:"architecture.md"};function s(n,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="kubernetes-gateway-exporter-documentation" tabindex="-1">Kubernetes Gateway Exporter Documentation <a class="header-anchor" href="#kubernetes-gateway-exporter-documentation" aria-label="Permalink to &quot;Kubernetes Gateway Exporter Documentation&quot;">​</a></h1><p>Welcome to the internal documentation for the <strong>Kubernetes Gateway Exporter</strong>. This repository provides an inventory of logical routing relationships exposed through Kubernetes Gateway API resources.</p><h2 id="core-traceability-map" tabindex="-1">Core Traceability Map <a class="header-anchor" href="#core-traceability-map" aria-label="Permalink to &quot;Core Traceability Map&quot;">​</a></h2><p>This project adheres strictly to the &quot;Docs-First&quot; rule. No core application logic is written without architectural justification. Every core component in the Go source code links back to the documents listed here.</p><blockquote><p><strong>Note on Documentation Strategy:</strong> This repository uses a hybrid documentation approach.</p><ul><li><strong><a href="./../openspec/specs/">OpenSpec (<code>openspec/specs/</code>)</a></strong> defines the functional requirements.</li><li><strong><a href="./adrs/">ADRs (<code>docs/adrs/</code>)</a></strong> define the technical architecture and decisions. The functional specs actively link to their corresponding technical ADRs.</li></ul></blockquote><h3 id="architecture-decision-records-adrs" tabindex="-1">Architecture Decision Records (ADRs) <a class="header-anchor" href="#architecture-decision-records-adrs" aria-label="Permalink to &quot;Architecture Decision Records (ADRs)&quot;">​</a></h3><ul><li><a href="./adrs/001-k8s-informers.html">ADR-001: Kubernetes Informers Strategy</a> - Details the choice of using cache-backed informers for resource mapping.</li><li><a href="./adrs/002-ip-resolution.html">ADR-002: Gateway Address Resolution</a> - Explains portable address extraction from <code>Gateway.status.addresses</code>.</li><li><a href="./adrs/003-testing-strategy.html">ADR-003: Testing Strategy</a> - Defines table-driven mapping tests and Prometheus contract tests.</li><li><a href="./adrs/004-otel-metrics.html">ADR-004: OpenTelemetry Strategy</a> - Explains the OTLP push model and Observable Gauge implementation for OTEL.</li><li><a href="./adrs/005-security.html">ADR-005: Security Hardening</a> - Documents HTTP timeouts (Slowloris protection), distroless containers, and future recommendations.</li><li><a href="./adrs/006-metric-labels-expansion.html">ADR-006: Exposure Metric Identity</a> - Defines the flattened Gateway API relationship and metric labels.</li></ul><h3 id="api-specifications" tabindex="-1">API Specifications <a class="header-anchor" href="#api-specifications" aria-label="Permalink to &quot;API Specifications&quot;">​</a></h3><ul><li><a href="./api/openapi.yaml">OpenAPI 3.0 Specification</a> - Defines the internal management and health endpoints exposed by the exporter (<code>/healthz</code>, <code>/readyz</code>, <code>/metrics</code>).</li></ul><h3 id="operational-guides" tabindex="-1">Operational Guides <a class="header-anchor" href="#operational-guides" aria-label="Permalink to &quot;Operational Guides&quot;">​</a></h3><ul><li><a href="./testing-on-kind.html">Testing locally on kind</a> - Builds and verifies the exporter without installing a Gateway controller.</li></ul><h3 id="key-domain-relationships" tabindex="-1">Key Domain Relationships <a class="header-anchor" href="#key-domain-relationships" aria-label="Permalink to &quot;Key Domain Relationships&quot;">​</a></h3><p>The core logic of this exporter resolves the following relationship chain using Kubernetes informers: <code>Gateway</code> -&gt; <code>Listener</code> -&gt; <code>HTTPRoute</code> -&gt; <code>Service</code></p><p>The metric represents logical routing relationships. It does not enumerate Pods, Pod IPs, Endpoints, or EndpointSlices behind a Service.</p><p>Labels exposed by the resulting Prometheus metric (<code>exposed_route_info</code>):</p><ul><li><code>namespace</code></li><li><code>gateway_name</code></li><li><code>route_name</code></li><li><code>route_namespace</code></li><li><code>hostname</code></li><li><code>listener_name</code></li><li><code>http_path</code></li><li><code>service_name</code></li><li><code>backend_namespace</code></li><li><code>backend_port</code></li><li><code>lb_type</code> (<code>internal</code> or <code>external</code>, heuristically inferred from the GatewayClass name)</li><li><code>ip_address</code> (read from <code>Gateway.status.addresses</code>)</li></ul>',16)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
